export class BridgeClient {
 constructor(onChange){this.local=!!document.querySelector('meta[name="gtbv-bridge"]');this.onChange=onChange;this.state=null;this.token='';this.busy=false;try{this.token=sessionStorage.getItem('gtbv-bridge-token')??'';}catch{} }
 async request(path,{method='GET',body,binary=false}={}){const response=await fetch(path,{method,headers:{...(this.token?{Authorization:'Bearer '+this.token}:{}),...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,cache:'no-store',signal:AbortSignal.timeout(8000)});if(!response.ok){let data;try{data=await response.json();}catch{}if(response.status===401&&path!=='/api/pair'){this.token='';try{sessionStorage.removeItem('gtbv-bridge-token');}catch{}}throw Error(data?.error??'El puente no respondió correctamente.');}return binary?response.arrayBuffer():response.json();}
 async pair(pin){const result=await this.request('/api/pair',{method:'POST',body:{pin}});this.token=result.token;try{sessionStorage.setItem('gtbv-bridge-token',this.token);}catch{}await this.refresh();}
 async unpair(){try{await this.request('/api/unpair',{method:'POST',body:{}});}finally{this.token='';this.state=null;try{sessionStorage.removeItem('gtbv-bridge-token');}catch{}this.onChange();}}
 async refresh(){if(!this.local||!this.token||this.busy)return;this.busy=true;try{this.state=await this.request('/api/state');this.error='';}catch(e){this.state=null;this.error=e.message;}finally{this.busy=false;this.onChange();}}
 start(){if(!this.local)return;this.onChange();this.refresh();this.timer=setInterval(()=>this.refresh(),1000);}
}
export function localBridgeUrl(value){try{const url=new URL(value);const p=url.hostname.split('.').map(Number);const valid=p.length===4&&p.every(n=>Number.isInteger(n)&&n>=0&&n<=255)&&(p[0]===10||p[0]===192&&p[1]===168||p[0]===172&&p[1]>=16&&p[1]<=31||p[0]===127);if(url.protocol!=='http:'||!valid||url.username||url.password||url.pathname!=='/'||url.search||url.hash)return null;return url.origin;}catch{return null;}}
